insert into public.learning_cards (lesson_id, position, title, blocks) values ('acaaebbf-6b01-511f-94bc-ef3a1962be95', 1, 'Le King', '[{"type":"text","text":"Dans les années 1950, Elvis Presley fait danser l’Amérique sur du rock’n’roll. Sa maison de Memphis, Graceland, est aujourd’hui un musée."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('acaaebbf-6b01-511f-94bc-ef3a1962be95', 2, 'Quatre garçons de Liverpool', '[{"type":"list","items":["John Lennon","Paul McCartney","George Harrison","Ringo Starr"]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('acaaebbf-6b01-511f-94bc-ef3a1962be95', 3, 'Des albums mythiques', '[{"type":"text","text":"Sgt. Pepper’s (1967) révolutionne l’album pop. En 1969, la pochette d’Abbey Road montre les quatre Beatles traversant un passage piéton. Le groupe se sépare en 1970."}]'::jsonb);
