insert into public.learning_cards (lesson_id, position, title, blocks) values ('c11f8ec6-bad4-5638-ad9d-781d7a39d734', 2, 'Queen', '[{"type":"text","text":"Freddie Mercury et Queen sortent Bohemian Rhapsody en 1975, un morceau de six minutes sans vrai refrain. En 1985, leur concert au Live Aid est souvent cité comme le plus grand concert de rock."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('c11f8ec6-bad4-5638-ad9d-781d7a39d734', 3, 'L’homme aux mille visages', '[{"type":"text","text":"David Bowie se réinvente sans arrêt. Son double le plus célèbre : Ziggy Stardust, rock star venue de l’espace."}]'::jsonb);
